INSERT IGNORE INTO `courses` (`id`, `title`, `description`, `short_description`, `thumbnail`, `is_published`, `certificate_enabled`, `enrollment_fields`, `created_at`, `updated_at`, `cover_image`, `duration`, `start_date`, `venue`, `batch`, `show_batch`, `target_audience`, `price`, `instructor_id`, `views`, `level`, `category`, `deleted_at`, `counselor_phone`, `whatsapp_message`, `registration_status`) VALUES
(20, 'INCOTERMS® 2020', 'INCOTERMS® 2020 — Practical Guide for Commercial & Supply Chain Professionals\r\n\r\nIncoterms® are essential for anyone involved in international trade, commercial operations, logistics, shipping, banking, and supply chain management. This practical training will help participants understand how Incoterms® 2020 define the cost, risk, responsibility, and delivery obligations between buyers and sellers.\r\n\r\nThe session will cover all 11 Incoterms® 2020 rules, with practical explanations and real-world examples focused on export-import operations.\r\n\r\nKey Topics:\r\n• Understanding all 11 Incoterms® 2020 rules\r\n• Buyer & seller responsibilities\r\n• Transfer of cost and risk\r\n• FOB, CFR, CIF, FCA, CPT, CIP, DAP, DDP and others\r\n• Incoterms® and shipping/logistics\r\n• Incoterms® and L/C & banking\r\n• Documentation and contractual implications\r\n• Common mistakes in selecting Incoterms®\r\n• Practical cases from international trade and RMG business\r\n\r\nWho Should Attend:\r\nCommercial, Export-Import, Supply Chain, Logistics, Shipping, Banking, Merchandising, and Trade Finance professionals, as well as students and career aspirants interested in international trade.\r\n\r\nLearn the rules. Understand the risks. Make better trade decisions.', 'INCOTERMS® 2020 Understand Cost, Risk & Responsibility in International Trade — from contract to shipment.', 'course_covers/y95vDIHOMKslJfutX3HLRTNceFmdY5s3CvV0e2qA.png', 1, 0, NULL, '2026-11-10 18:33:41', '2026-11-16 02:20:17', 'course_covers/y95vDIHOMKslJfutX3HLRTNceFmdY5s3CvV0e2qA.png', '1.5 HOURS', '2026-11-20', 'Online Live (Zoom)', 'Starting Time: 08:30 PM', 1, NULL, '200.00', 2, 324, NULL, 'COMMERCIAL MANAGEMENT', NULL, '+8801744-542955', NULL, 'open'),
(17, 'Communication Etiquette: Essential Skills for Professional Success', 'Communication Etiquette: Essential Skills for Professional Success\r\n\r\nTopics Covered\r\n\r\nDefinition of Communication Etiquette\r\n\r\nVerbal Nuances: Choosing the Right Words, Tone, and Language\r\n\r\nNon-Verbal Signals: Body Language, Facial Expressions, and Eye Contact\r\n\r\nThe Written Word: Professional Writing and Workplace Communication\r\n\r\nTech-Savvy Manners: Digital Etiquette in the Modern Workplace\r\n\r\nBridging Cultures: Cross-Cultural Communication and Professional Respect\r\n\r\nWhat to Say in Different Management Situations: Communicating with Confidence and Clarity\r\n\r\nEmail Communication: Best Practices for Professional and Effective Emails\r\n\r\nManaging Difficult Conversations: Handling Conflict, Criticism, and Disagreement Professionally\r\n\r\nThings Not to Say in a Leadership Interview: Common Communication Mistakes to Avoid\r\n\r\nHow High Performers Apologize: Taking Responsibility, Rebuilding Trust, and Learning from Mistakes\r\n\r\n10 Unprofessional Phrases That Can Damage Your Professional Reputation', 'Master professional communication, workplace etiquette, leadership conversations, and the language that builds trust and credibility.', 'course_covers/nxRl9HfJyRnR2b13tikJePEbYMfW8lAPEg01lkny.jpg', 0, 0, NULL, '2026-10-25 01:37:17', '2026-11-01 23:35:53', 'course_covers/nxRl9HfJyRnR2b13tikJePEbYMfW8lAPEg01lkny.jpg', NULL, NULL, 'Online', '03', 1, 'Students, Fresh Graduates, Working Professionals, Team Leaders, Managers, and Aspiring Leaders', '0.00', 2, 9, NULL, 'Soft Skills', '2026-11-01 23:35:53', NULL, NULL, 'open'),
(18, 'Communication Skills for Career Success.', 'Communication Skills for Career Success\r\n\r\nEffective communication and strong leadership skills are essential for professional growth. Join our free training session to enhance your communication abilities, build confidence, and develop the skills needed to succeed in your career.\r\n\r\nTraining Highlights:\r\n\r\nProfessional Communication Skills\r\n\r\nWorkplace Communication Etiquette\r\n\r\nLeadership and Confidence Building\r\n\r\nCommunication for Career Success\r\n\r\nTrainer: MD. Shahneoage Hossain\r\nDate: 06 December 2027\r\nTime: 9:00 PM\r\nPlatform: Google Meet\r\nRegistration: Contact us for details.\r\n\r\nOrganized by ACS Academy – Academy of Commercial & Supply Chain\r\nLearn | Grow | Lead\r\n\r\nTake a step toward becoming a more confident communicator and a stronger professional. Join us and invest in your career growth!', 'Master professional communication, workplace etiquette, leadership conversations, and the language that builds trust and credibility.', 'course_covers/vd5a7hbuZluTHXlZwxDzpIMoHyC9VOHG4ufd2aEw.png', 1, 0, '[{\"name\":\"name\",\"label\":\"Full Name\",\"type\":\"text\",\"is_required\":true,\"is_enabled\":true,\"is_system\":true,\"placeholder\":\"e.g. Tanvir Ahmed\",\"options\":null},{\"name\":\"phone\",\"label\":\"Mobile (11 Digits)\",\"type\":\"tel\",\"is_required\":true,\"is_enabled\":true,\"is_system\":true,\"placeholder\":\"017xxxxxxxx\",\"options\":null},{\"name\":\"email\",\"label\":\"Email Address\",\"type\":\"email\",\"is_required\":true,\"is_enabled\":true,\"is_system\":true,\"placeholder\":\"name@company.com\",\"options\":null},{\"name\":\"training_mode\",\"label\":\"Preferred Attendance Mode\",\"type\":\"select\",\"is_required\":true,\"is_enabled\":true,\"is_system\":true,\"placeholder\":\"\",\"options\":{\"online_zoom\":\"Live Online (Zoom)\",\"in_person\":\"Executive Campus\"}}]', '2026-10-25 01:41:54', '2026-11-16 01:57:11', 'course_covers/vd5a7hbuZluTHXlZwxDzpIMoHyC9VOHG4ufd2aEw.png', '1.5 hour', '2026-11-07', 'Online Live (Zoom)', 'Completed', 1, 'This program is ideal for all corporate job holders, students, fresh graduates, working professionals, team leaders, managers, and aspiring leaders who want to enhance their professional skills, strengthen their practical knowledge, improve workplace performance, and accelerate career growth.', '0.00', 12, 1169, 'n/a', 'LEADERSHIP & SOFT SKILLS', NULL, '01744-542955', NULL, 'closed'),
(19, 'Mastering Import-Export Operations & Commercial Management.', 'Introduction\r\nObjective of this course is to improve and upgrade the skills of the Commercial & Supply\r\nChain professionals dealing with Importing and Exporting functions in respective\r\norganizations. International trade also is one of the popular ways of self-employment\r\nentrepreneurship in the present world.\r\nInternational trade is divided into two major activities. They are Import & Export. Major\r\nissues in the import and export business are LC opening, bill of entry, bill of leading,\r\ninsurance, freight forwarding, Customs clearing, and related domestic & international\r\nprocessing & procedures.\r\nCourse Fee: course Fee: BDT 3,500\r\n💳\r\nPayable in 03 Easy Installments (BDT 1,000 + 1,000 + 1,500).\r\n🎉\r\nEarly Bird Offer: BDT 3,000!\r\nMethodology:\r\nExercise, PowerPoint Presentation, Question and answer session.\r\nDAY-01: \r\nInternational Trade, L/C & Trade Finance\r\nDATE: 05-Dec-2026\r\nTime:9.00 PM TO 10.30 PM\r\n1. Introduction to International Trade\r\n2. L/C Details for International Trade\r\n3. Master L/C & Back-to-Back L/C\r\n4. L/C at Sight & Transferable L/C\r\n5. Irrevocable L/C & Confirmed L/C\r\n6. L/C Opening Documents\r\n7. TT Payment\r\n8. Questions & Answers Session\r\n9. Import Cost Calculation\r\n10. UCP 600 & International Standard Banking Practice (ISBP)\r\n11. Trade Finance Facilities: Pre-Shipment & Post-Shipment Financing\r\n12. SWIFT Messages, L/C Amendments & Bank-to-Bank Correspondence\r\nDAY-02: \r\nCustoms, HS Code, Duties & Regulatory Compliance\r\nDATE: 19-Dec-2026\r\nTime:9.00 PM TO 10.30 PM\r\n13. Correct H.S. Code Selection\r\n14. Calculation of Customs Duty & Taxes\r\n15. List of Shipping Documents\r\n16. Discrepant Documents\r\n17. International Payments\r\n18. Payment Risks in International Trade\r\n19. ASYCUDA\r\n20. Benefits of New S.R.O.\r\n21. Customs Valuation, Assessable Value & Rules of Origin\r\n22. Import Permits, Regulatory Approvals & Compliance Requirements\r\n23. Digital Customs Clearance, Electronic Documentation & Paperless Trade\r\n.Day - 3: \r\nExport-Import Documentation, Incoterms & Logistics\r\nDATE: 26-Dec-2026\r\nTime:9.00 PM TO 10.30 PM\r\n24. Sourcing of Buyers\r\n25. Sourcing of Suppliers\r\n26. Documents for Export-Import\r\n27. Incoterms Selection (FOB, CFR, CIF, CPT, etc.)\r\n28. Bill of Entry & IGM\r\n29. Bill of Export & EGM\r\n30. Bill of Lading & Bill of Exchange\r\n31. LCL & FCL Cargo\r\n32. Import Problems & Solutions\r\n33. Export Problems & Solutions\r\n34. Incoterms 2020: Practical Application, Cost Allocation & Risk Transfer\r\n35. Container Booking, Shipping Instructions, VGM & Shipping Line Coordination\r\n36. Shipment Tracking, Port Congestion & Logistics Disruption Management\r\nDay - 4: \r\nCommercial Operations, Banking & Payment Management\r\nDATE: 09-JAN-2026\r\nTime:9.00 PM TO 10.30 PM\r\n37. Import Without L/C\r\n38. Commercial Functions with C&F Agents\r\n39. Commercial Functions with Freight Forwarders\r\n40. Advance TT Payment\r\n41. Issuing Bank & Advising Bank\r\n42. Confirming Bank & Negotiating Bank\r\n43. Lien Bank\r\n44. Documentary Collection: Documents Against Payment (D/P) & Documents Against\r\nAcceptance (D/A)\r\n45. Bank Charges, Exchange Rate Risk & Foreign Currency Payment Management\r\n46. Trade-Based Money Laundering (TBML), Sanctions Screening & Trade Compliance\r\nDay - 5: \r\n.\r\nCosting, Shipping, Export Incentives & Procurement\r\nDATE: 23-JAN-2026\r\nTime:9.00 PM TO 10.30 PM\r\n47. Import Cost Calculation\r\n48. Export Cost Calculation\r\n49. Export Incentives\r\n50. Feeder Vessel & Mother Vessel\r\n51. House B/L & Master B/L\r\n52. Insurance Cover Note & Insurance Policy\r\n53. Bonded Warehouse Management\r\n54. Proforma Invoice (PI) & Commercial Invoice\r\n55. Air Waybill (AWB) & Air Shipment\r\n56. Import VAT Calculation\r\n57. Freight Costing, Freight Negotiation & Logistics Cost Optimization\r\n58. Supplier Evaluation, Procurement Planning & Purchase Order Management\r\n59. Landed Cost Analysis, Export Pricing & Profitability Assessment\r\nDay - 6:  Full-day, in-person workshop.\r\nFocus: Practical commercial operations, international trade, procurement,\r\nlogistics, and end-to-end supply chain optimization\r\nFocus: Practical commercial operations, international trade, procurement,\r\nlogistics, and end-to-end supply chain optimization\r\nFocus: Practical commercial operations, international trade, procurement,\r\nlogistics, and end-to-end supply chain optimization\r\nDATE: 30-JAN-2026\r\nDATE: 30-JAN-2026\r\nTime: AFTERNOON TO EVENING\r\nDATE: 30-JAN-2026\r\nTime: AFTERNOON TO EVENING\r\nTime: AFTERNOON TO EVENING\r\nCertificate of Participation\r\nSnacks & Refreshments/Tea-cofee-Adda\r\nFace-to-Face Q&A with Industry Leaders\r\nExpert Insights & Best Practices\r\nReal-Life Case Studies & Solutions\r\nHands-On Practical Workshop\r\nImport-Export Documentation Insights\r\nERP/SAP & Supply Chain Operations\r\nCost Optimization & Negotiation Skills\r\nCareer Development & Skill Enhancement\r\nNetworking with Industry Professionals\r\nKnowledge Sharing & Group Discussions\r\nCommercial Problem-Solving Techniques\r\nKPI & Performance Improvement\r\nCertificate Distribution & Closing Session\r\nDiscussion :\r\nMd. Delwar Hossain Bhuiyan\r\nCommercial & Supply Chain Consultant.\r\nLead Trainer-EXPORT-IMPORT\r\n26 Years Experiance ,Export\r\nImport,Banking,Customes,Bond\r\nInternational Trading.\r\nMd.Rayhan khan\r\nCommercial, Banking & Logistics Training\r\nSpecialist\r\nAGM, Dekko ISHO Group\r\nCertified Soft Skills Trainer | Lead Trainer \r\nTraining of Trainers (ToT)\r\n15 Years of Industry Experience\r\nMD.Shahneoage Hossain\r\n60. New Import Policy\r\n61. New Export Policy\r\n62. Price Negotiation\r\n63. C&F Documents\r\n64. Foreign Procurement\r\n65. Supply Chain Management (SCM) & End-to-End Supply Chain Process\r\n66. Inventory Management, Lead Time & Supply Chain Cost Optimization\r\n67. Shipment Planning, Logistics Coordination & On-Time Delivery Management\r\n68. ERP/SAP-Based Commercial Operations & Supply Chain Data Management\r\n69. Export Order Management, Production Follow-Up & Shipment Execution\r\n70. Supply Chain Risk Management, Business Continuity & Contingency Planning\r\n71. Supply Chain Performance Measurement: KPIs, OTIF & Vendor Performance', '**Import-Export, Commercial & Supply Chain Management Training**  Upgrade your professional skills in international trade, L/C and trade finance, import-export documentation, customs procedures, HS Code, Incoterms 2020, shipping and logistics, banking, procurement, costing, and end-to-end supply chain management.  This practical training program combines expert guidance, real-life case studies, interactive Q&A sessions, and a full-day, in-person workshop to help Commercial & Supply Chain professionals develop job-ready skills and improve operational efficiency.  **Course Fee:** BDT 3,500 **Early Bird Offer:** BDT 3,000 **Payment Facility:** 3 easy instalments **Training Format:** Online sessions + full-day practical workshop **Certificate:** Certificate of Participation', 'course_covers/HqTr7f3oj6focr0dBxnjFKKObvZrZ9EwI7AIVKul.jpg', 0, 0, NULL, '2026-10-27 16:27:53', '2026-11-10 12:09:21', 'course_covers/HqTr7f3oj6focr0dBxnjFKKObvZrZ9EwI7AIVKul.jpg', '02 Month', '2026-12-05', 'ONLINE(ZOOM)', '1ST BATCH', 1, 'Freshers and aspiring Commercial Professionals\r\n\r\nJunior & Mid-Level Commercial Executives and Officers\r\n\r\nImport & Export Documentation Professionals\r\n\r\nSupply Chain, Procurement & Sourcing Professionals\r\n\r\nShipping, Logistics & Freight Forwarding Professionals\r\n\r\nBanking, Trade Finance & LC Operations Professionals\r\n\r\nCustoms, C&F Agents & Bond Management Professionals\r\n\r\nMerchandising Professionals involved in Export-Import Operations\r\n\r\nFinance & Accounts Professionals handling International Trade\r\n\r\nBusiness Owners, Entrepreneurs & Import-Export Traders\r\n\r\nERP/SAP Users involved in Commercial & Supply Chain Operations\r\n\r\nProfessionals seeking career development and practical expertise in International Trade', '3500.00', 2, 15, 'Certificate', 'Export – Import', '2026-11-10 12:09:21', NULL, NULL, 'open');
