INSERT IGNORE INTO `instructors` (`id`, `name`, `title`, `expertise`, `avatar`, `bio`, `email`, `phone`, `order`, `is_active`, `user_id`, `deleted_at`, `created_at`, `updated_at`, `department`, `departments`, `department_role`) VALUES
(5, 'MANILA NIMA', 'Deputy Manager |Commercial & Supply Chain', 'Commercial |Banking |Customes|Bond|Ud', 'instructors/Kqc7JYpPCtcUpjSpB48ZoN2O8kNTZj9LQOYbPmkf.jpg', 'Manila Nima  is an experienced Commercial and Supply Chain professional with 12 years of expertise in Commercial Operations, Export-Import Management, International Trade, Banking, Bond and Customs Management. She has developed strong practical knowledge of export-import documentation, trade procedures, banking operations, shipment coordination, and regulatory compliance. \r\n\r\nWith a strong understanding of commercial operations and international trade practices, she brings valuable industry insights and hands-on experience in managing complex commercial activities. Her professional experience and practical knowledge make her a valuable contributor to the Commercial and Supply Chain sector.', 'commercialacademy868@gmail.com', NULL, 0, 1, 2, NULL, '2026-10-27 16:35:14', '2026-11-15 02:15:10', 'Commercial Management', NULL, 'team_member'),
(6, 'instructor 04', 'sd', 'sd', NULL, NULL, 'faculty_1793094357_352@cab-academy.com', NULL, 4, 1, 9, '2026-10-27 16:46:28', '2026-10-27 16:45:58', '2026-10-27 16:46:28', NULL, NULL, 'team_member'),
(11, 'MD. Shahneoage Hossain', 'SUPPLY CHAIN & OPERATION', 'PGDSCM,PGDCVTTM,CSCP(TM),Lean Six Sigma (Yellow Belt),CACC(Partly Qualified),LLB,Masters(Accounting), SCM Trainer at BIHRMSCM, Soft Skill Trainer at : Career Marathon', 'profiles/profile_1794681056_6af8a8e0831e5.jpeg', NULL, 'sajdh@gmail.com', NULL, 6, 1, 12, NULL, '2026-10-27 16:52:07', '2026-11-15 02:30:56', 'Professional Skills & Leadership Development', NULL, 'head'),
(7, 'Md. Delwar Hossain Bhuiyan', 'Commercial-Supply Chain-International Business', 'Export |Import |Bond|Customs|Banking & Supply Chain', 'instructors/oSaiPXcLwPECh0BNEcf8GxGkQ9IAlYbx8GNTZ2pS.png', 'Having achieved masters degree from University of Dhaka in 1991, Mr. Bhuiyan started his career with an international trading company and worked for LG Corporation, Korea, Sumitomo Corporation, Singapore, Mitsui Corporation, Mitsubishi Corp. Japan, Hyundai Corporation, Singapore at later stage of his life. Mr Delwar Hossain has established his own consulting firm, Desh Consulting Ltd, and providing professional solutions in Banking, Marketing, Commercial, Documentation, Customs procedures, Shipping procedures, International Trade, E-tender, L/C, Indenting Business, C & F Agent Business, Project Profiling, Buying House and Export- Import Business. He has trained over 15,000 new entrepreneurs, professionals, business owners, technical and management experts and still counting in. He attended many trainings and seminars on international business and got experience in import, export, indenting and international tender business. He participated in many international tender with PDB, REB, DESA, WASA, DGDP and Biman Bangladesh Airlines. He has been with international business for about 26 years, where he deals with Banks, Insurance, Inspection Co., Customs Authority, C&F agents, DCCI, BIAA, BOI, EPB and others business related organizations.', 'delwer@cab-academy.com', NULL, 2, 1, 32, NULL, '2026-10-27 16:48:31', '2026-11-15 02:16:22', 'Supply Chain Management', NULL, 'team_member'),
(9, 'Mohammad Rayhan Khan', 'AGM, Dekko ISHO Group | Commercial, Banking & Logistics Training Specialist | Certified Soft Skills Trainer | Lead Trainer', 'Commercial International Trade & Industry Expert', 'instructors/hKx1Hy6p1KvWlNkefOYVu45b5eT9hRXK7ek51CeG.png', 'Mohammad Rayhan Khan is an experienced Commercial, Banking and Logistics professional currently serving as Assistant General Manager (AGM) at Dekko ISHO Group. A graduate of the University of Dhaka, he brings 15 years of industry experience in commercial operations, international trade, banking, logistics and supply chain coordination.\r\n\r\nHe is a Certified Soft Skills Trainer, Lead Trainer and Training of Trainers (ToT) professional, combining practical industry knowledge with professional training expertise. His focus is on developing industry-ready professionals through practical learning, effective communication, leadership development and knowledge sharing.', 'kefjkwef@gmail.com', NULL, 5, 1, 10, NULL, '2026-10-27 16:51:38', '2026-11-15 02:21:29', 'Commercial Management', NULL, 'head'),
(10, 'Dr.Md. Aynul Hoque', 'Assistant Professor – Supply Chain Management', 'Supply Chain Management', 'instructors/UrfjTjYp2WpfmuxECfqmt5oxeZEpZjqKZqhRTwXV.jpg', 'Md. Aynul Hoque is an accomplished academic and supply chain professional currently serving as Assistant Professor in the Department of Supply Chain Management & Operations at IUBAT. He holds a PhD from the University of Malaysia and brings extensive academic and professional expertise in Operations and Supply Chain Management. He is also a Lead Trainer in Operations & Supply Chain Management and has previously served as Adjunct Faculty at North South University (NSU), United International University (UIU), UCSI University, and American International University-Bangladesh (AIUB). His areas of expertise include strategic supply chain management, operations planning, logistics, procurement, inventory management, and operational excellence.', 'dshfjklsdh@gmail.com', NULL, 3, 1, 11, NULL, '2026-10-27 16:51:54', '2026-11-15 02:17:17', 'Supply Chain Management', NULL, 'head'),
(12, 'SAIDUR RAHMAN ROCKY', 'Corporate Faculty Fellow', 'International Trade & Industry Masterclasses', 'profiles/profile_1794680723_6af8a79360da1.jpeg', 'Corporate Professional | Commercial & Supply Chain Expert | RMG Industry | Educator | Career Development Advocate\r\n\r\nSaidur Rahman Rocky is an experienced Commercial and Supply Chain professional with over 12 years of experience in Bangladesh\'s Ready-Made Garments (RMG) and export-oriented industries.\r\n\r\nCurrently associated with Echotex Limited, he specializes in Commercial Operations, Supply Chain Management, Shipping & Logistics, Export Documentation, Trade Finance and International Trade Operations.\r\n\r\nHe has extensive practical experience in export-import management, banking operations, international shipping, trade finance and cross-functional business operations.\r\n\r\nAlongside his corporate career, he is involved in academic teaching and professional development initiatives, contributing to knowledge sharing, industry networking and the development of future industry professionals.\r\n\r\nHe is also associated with the Academy of Commercial & Supply Chain (ACS), a community-driven professional learning initiative focused on connecting professionals, empowering learners and developing industry-ready talent.\r\n\r\nThrough ACS, he advocates practical learning, career advancement, leadership development and bridging the gap between academic knowledge and real-world industry requirements.\r\n\r\nAcademic Qualifications\r\n\r\n- MBA in Supply Chain Management\r\n- MBA in Finance\r\n- Bachelor of Business Administration (BBA)\r\n- Postgraduate Qualification in Supply Chain Management\r\n\r\nAreas of Expertise\r\n\r\n- Commercial & Export-Import Management\r\n- Supply Chain Management\r\n- International Trade & Trade Finance\r\n- Shipping & Logistics\r\n- Export Documentation & Compliance\r\n- Banking & LC Operations\r\n- ERP & SAP\r\n- Business Communication & Professional Development\r\n- Leadership & Management Development\r\n- Career Planning & Personal Branding\r\n- Negotiation, Presentation & Public Speaking\r\n- Industry Networking & Knowledge Sharing\r\n\r\nProfessional Vision\r\n\r\nTo bridge the gap between academic knowledge and industry practices by developing skilled professionals, empowering future leaders, building meaningful professional networks and promoting continuous learning.\r\n\r\nCONNECT • EMPOWER • GROW • LEAD', 'saidurvub@gmail.com', '01917054664', 6, 1, 13, NULL, '2026-11-15 02:18:01', '2026-11-15 02:25:23', 'Career Development', NULL, 'head');
