INSERT IGNORE INTO `payment_methods` (`id`, `provider_name`, `account_number`, `account_type`, `instructions`, `logo`, `is_active`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'bKash Merchant', '01917-054664', 'Personal', '1. Go to your bKash app and select \'Make Payment\'.\r\n2. Enter Merchant Number: 01917-054664.\r\n3. Enter the exact Course Fee.\r\n4. Enter Reference: Course Title or Your Mobile.\r\n5. Enter your PIN and confirm.\r\n6. Copy the TrxID and submit it below.', NULL, 1, '2026-10-25 00:58:58', '2026-10-30 10:54:30', NULL),
(2, 'Nagad Personal / Merchant', '01917-054664', 'Personal', '1. Dial *167# or open Nagad App.\r\n2. Select Payment.\r\n3. Enter Number: 01917-054664.\r\n4. Input Amount and Reference.\r\n5. Save TrxID and submit below.', NULL, 1, '2026-10-25 00:58:58', '2026-10-30 10:54:21', NULL),
(3, 'Bank Transfer', '000-000-000000', 'Corporate Account', 'Bank Name: Corporate Commercial Bank PLC\r\nBranch: Principal Corporate Branch, Dhaka\r\nAccount Name: CAB Academy\r\nA/C Number: 000-000-000000\r\nRouting: 000000000\r\nPlease upload deposit slip or bank receipt.', NULL, 0, '2026-10-25 00:58:58', '2026-10-29 01:22:22', NULL);
