(77, 'landing_jobs_enabled', '1', 'text', 'frontend', '2026-10-25 01:49:28', '2026-11-10 12:05:56'),
(78, 'landing_jobs_title', 'Career Opportunities', 'text', 'frontend', '2026-10-25 01:49:28', '2026-11-15 01:55:50'),
(79, 'landing_jobs_subtitle', 'Explore openings posted exclusively for ACS Academy certified professionals', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-30 13:40:11'),
