(81, 'landing_jobs_btn_url', '/jobs', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-25 01:49:28'),
(82, 'about_hero_badge', 'Academy of Commercial & Supply Chain -ACS', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-28 15:19:55'),
(83, 'about_hero_title', 'South Asia\'s Premier Institute for Commercial Trade & Industry Mastery', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-25 01:49:28'),
(84, 'about_hero_desc', 'The Academy of Commercial & Supply Chain (ACS) is a professional learning platform dedicated to bridging the gap between industry knowledge and practical expertise. We empower students, fresh graduates, and working professionals with industry-oriented training in Commercial Operations, International Trade, Import–Export Documentation, Trade Finance, Logistics, and Supply Chain Management.\r\n\r\nThrough experienced industry professionals, practical learning approaches, and accessible training opportunities, ACS aims to develop competent, confident, and career-ready professionals who can contribute meaningfully to the evolving business landscape.\r\n\r\n**Learn. Grow. Lead.**', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-28 15:19:55'),
(85, 'about_stat_graduates', '5,000+', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-25 01:49:28'),
(86, 'about_stat_graduates_label', 'Corporate Alumni', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-25 01:49:28'),
(87, 'about_stat_curriculum', '98%', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-25 01:49:28'),
(88, 'about_stat_curriculum_label', 'Practical Curriculum', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-25 01:49:28'),
(89, 'about_stat_faculty', '25+', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-25 01:49:28'),
(90, 'about_stat_faculty_label', 'Distinguished Faculty', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-25 01:49:28'),
(91, 'about_stat_partners', '120+', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-25 01:49:28'),
(92, 'about_stat_partners_label', 'Corporate Partners', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-25 01:49:28'),
(93, 'about_mission_title', 'Our Mission', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-25 01:49:28'),
(94, 'about_mission_text', 'Our mission is to bridge the gap between academic knowledge and industry requirements by delivering practical, affordable, and industry-oriented professional training in Commercial, International Trade, Logistics, and Supply Chain Management.\r\n\r\nWe are committed to making quality knowledge accessible, empowering individuals with relevant skills, connecting learners with industry expertise, and developing competent professionals who can contribute to organizational success and sustainable industry growth.\r\n\r\n**Learn. Grow. Lead.**', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-28 15:19:55'),
(95, 'about_vision_title', 'Our Vision', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-25 01:49:28'),
(96, 'about_vision_text', 'To become a trusted and recognized professional learning platform in Bangladesh and beyond, setting new standards in Commercial, International Trade, Logistics, and Supply Chain education.\r\n\r\nWe aspire to build a skilled, knowledgeable, and future-ready professional community by promoting practical learning, industry collaboration, continuous development, and accessible professional training—helping individuals advance their careers and contributing to a more competent and competitive workforce.\r\n\r\n**Learn. Grow. Lead.**', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-28 15:19:55'),
(97, 'about_philosophy_title', 'Core Philosophy', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-25 01:49:28'),
(98, 'about_philosophy_text', 'At the Academy of Commercial & Supply Chain (ACS), we believe that knowledge creates value when it can be applied in the real world. Professional development should go beyond theoretical learning to focus on practical skills, industry insights, and continuous improvement.\r\n\r\nOur philosophy is built on the belief that quality education should be accessible, industry experience should be shared, and learning should create meaningful opportunities for individuals and organizations.\r\n\r\nWe strive to foster a collaborative learning environment where professionals learn from experience, develop their capabilities, share knowledge, and grow together—contributing to a more skilled, ethical, and future-ready workforce.', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-28 15:19:55'),
(99, 'contact_campus_name', 'Academy of Commercial & Supply Chain (ACS)', 'text', 'frontend', '2026-10-25 01:49:28', '2026-10-28 15:19:55'),
