(130, 'landing_custom_sections', '[{\"id\":\"sec_1794386721935\",\"badge\":\"ACADEMY OF COMMERCIAL & SUPPLY CHAIN\",\"title\":\"Learn. Grow. Lead.\",\"subtitle\":\"Empowering Professionals Through Practical Learning, Industry Knowledge & Career Development.\",\"content\":\"ACS (Academy of Commercial & Supply Chain) is a professional learning, knowledge-sharing, and development platform dedicated to building a skilled and connected professional community.\\n\\nWe provide practical, industry-oriented training, expert-led workshops, career development guidance, and networking opportunities across Commercial, Supply Chain Management, Export-Import, Banking, Trade Finance, Logistics, Customs, and International Trade.\\n\\nThrough experienced industry professionals and real-world learning experiences, ACS aims to bridge the gap between academic knowledge and practical workplace skills.\\n\\nOur mission is to empower individuals to learn continuously, grow professionally, and lead confidently in an evolving business environment.\\n\\n**Learn. Grow. Lead. \\u2014 Together with ACS.**\",\"theme\":\"navy\",\"cta_text\":\"Explore ACS\",\"cta_url\":\"\\/about-us\",\"is_visible\":true}]', 'text', 'frontend', '2026-10-30 11:24:27', '2026-11-11 16:48:37'),
